-- 565: Original BrillaPrep WASSCE Social Studies sprint 3 beta questions, part 12 of 15 (batch wassce-social-studies-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_565_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_565_guard;
INSERT INTO _migration_565_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_045' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_edu' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following is a major consequence of teenage pregnancy for the education of the girl in Ghana?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Many pregnant girls drop out of school and lose qualifications and career prospects","B. It automatically earns the girl a scholarship","C. It shortens the school year for her classmates","D. It improves the girl’s academic performance"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Pregnancy and childcare interrupt schooling; many girls are withdrawn or drop out, ending their education and narrowing future employment options. The other options are plainly false — pregnancy brings no scholarship, has no effect on the school calendar, and the burden of childcare lowers rather than raises performance. Therefore the correct answer is A: Many pregnant girls drop out of school and lose qualifications and career prospects.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_045' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_565_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_046' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_edu' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'HIV CANNOT be transmitted through which of the following?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Unprotected sexual intercourse","B. Shaking hands with or sharing meals with an infected person","C. Transfusion of infected blood","D. Sharing contaminated needles and syringes"]' AND q.correct_answer IS 'B' AND q.explanation IS 'HIV spreads through specific body fluids during unprotected sex, contaminated blood and shared needles — not through casual contact such as handshakes, hugging, sharing food or mosquito bites. Knowing what does not transmit HIV helps adolescents avoid both infection and stigma towards infected persons. Therefore the correct answer is B: Shaking hands with or sharing meals with an infected person.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Select' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_046' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_565_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_047' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_edu' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'An adolescent who politely but firmly refuses to join friends in stealing an examination paper is demonstrating...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Low self-esteem","B. Rebellion against lawful authority","C. Assertiveness in resisting negative peer pressure","D. Aggressive behaviour"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Assertiveness is the ability to state one’s position and stand by sound values without aggression; refusing examination malpractice despite peer pressure is a textbook example. The student is confident rather than low in self-esteem, is upholding rather than defying lawful authority, and is calm rather than aggressive. Therefore the correct answer is C: Assertiveness in resisting negative peer pressure.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_047' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_565_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_048' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_edu' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following is a long-term effect of substance abuse on an adolescent?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Improved concentration in class","B. Stronger and warmer family relationships","C. Better physical fitness and stamina","D. Addiction and damage to vital organs such as the liver and the brain"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Prolonged abuse of alcohol, tramadol or cannabis produces dependence (addiction) and harms the liver, brain and heart, wrecking schooling and health. The other options describe benefits that substance abuse destroys: it impairs concentration, strains family ties and weakens the body. Therefore the correct answer is D: Addiction and damage to vital organs such as the liver and the brain.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Select' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_048' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_045', 'topic_wassce_p2_soc_edu', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'Which of the following is a major consequence of teenage pregnancy for the education of the girl in Ghana?', 'multiple_choice', NULL, '["A. Many pregnant girls drop out of school and lose qualifications and career prospects","B. It automatically earns the girl a scholarship","C. It shortens the school year for her classmates","D. It improves the girl’s academic performance"]', 'A', 'Pregnancy and childcare interrupt schooling; many girls are withdrawn or drop out, ending their education and narrowing future employment options. The other options are plainly false — pregnancy brings no scholarship, has no effect on the school calendar, and the burden of childcare lowers rather than raises performance. Therefore the correct answer is A: Many pregnant girls drop out of school and lose qualifications and career prospects.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_046', 'topic_wassce_p2_soc_edu', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'HIV CANNOT be transmitted through which of the following?', 'multiple_choice', NULL, '["A. Unprotected sexual intercourse","B. Shaking hands with or sharing meals with an infected person","C. Transfusion of infected blood","D. Sharing contaminated needles and syringes"]', 'B', 'HIV spreads through specific body fluids during unprotected sex, contaminated blood and shared needles — not through casual contact such as handshakes, hugging, sharing food or mosquito bites. Knowing what does not transmit HIV helps adolescents avoid both infection and stigma towards infected persons. Therefore the correct answer is B: Shaking hands with or sharing meals with an infected person.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Select', 'AO2', NULL, NULL, 'board_waec');
