INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_048', 'topic_wassce_p2_soc_edu', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'Which of the following is a long-term effect of substance abuse on an adolescent?', 'multiple_choice', NULL, '["A. Improved concentration in class","B. Stronger and warmer family relationships","C. Better physical fitness and stamina","D. Addiction and damage to vital organs such as the liver and the brain"]', 'D', 'Prolonged abuse of alcohol, tramadol or cannabis produces dependence (addiction) and harms the liver, brain and heart, wrecking schooling and health. The other options describe benefits that substance abuse destroys: it impairs concentration, strains family ties and weakens the body. Therefore the correct answer is D: Addiction and damage to vital organs such as the liver and the brain.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Select', 'AO2', NULL, NULL, 'board_waec');
